INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40011, 1, 2, 321, 1, 24001, 1, "リリ", 125801, "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", 0);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40011, 2, 2, 322, 1, 24001, 1, "クリア", 126001, "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", 0);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40011, 3, 2, 323, 1, 24001, 1, "プレシア", 126101, "んーと。\nこれ、あげる。\nはい", 0);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40011, 4, 2, 324, 2, 24001, 1, "リリ", 125801, "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", 0);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40011, 5, 2, 325, 2, 24001, 1, "クリア", 126001, "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", 0);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40011, 6, 2, 326, 2, 24001, 1, "プレシア", 126101, "お兄。\nきてくれて、うれしい", 0);
